mapper.select:
SELECT dpl.*, pd.name as disease_name, pd.type as disease_type, pd.image_url as disease_image_url, p.name as pesticide_name, p.category as pesticide_category, p.image_url as pesticide_image_url, eu.name as creator_name FROM disease_pesticide_link dpl LEFT JOIN pest_disease pd ON dpl.pd_id = pd.id LEFT JOIN pesticide p ON dpl.pesticide_id = p.id LEFT JOIN expert_user eu ON dpl.created_by = eu.id
AND pd.name LIKE CONCAT('%', #{diseaseName}, '%')
AND p.name LIKE CONCAT('%', #{pesticideName}, '%')
AND dpl.effectiveness = #{effectiveness}
ORDER BY dpl.created_at DESC LIMIT #{offset}, #{pageSize}
